fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cols: i32 = w / 8;
    let hmax: i32 = h / 2;
    let chunk: i32 = t / 8;
    let frac: i32 = t % 8;
    host::display::clear(0x000000);
    let mut k: i32 = 0;
    while k < cols {
        let a: i32 = hash(k * 31 + chunk * 7 + 1) % hmax;
        let b: i32 = hash(k * 31 + (chunk + 1) * 7 + 1) % hmax;
        let fh: i32 = a + (b - a) * frac / 8 + 8;
        host::display::fill_rect(k * 8, h - fh / 3, 7, fh / 3, 0xc02000);
        host::display::fill_rect(k * 8, h - fh * 2 / 3, 7, fh / 3, 0xf07010);
        host::display::fill_rect(k * 8, h - fh, 7, fh / 3, 0xffd040);
        k = k + 1;
    }
    host::display::present();
}
